import React, { useState, useRef, useEffect } from 'react';
import { 
  Bot, Send, Sparkles, X, ChevronRight, RefreshCw, 
  Dna, Droplets, Utensils, ShieldAlert, DollarSign, Copy
} from 'lucide-react';
import toast from 'react-hot-toast';

/**
 * mFk Farm AI Çiftlik Asistanı & Veri Danışmanı (Ultra-Modern Executive Edition)
 * Sürü verilerine dayalı akıllı veterinerlik, rasyon optimizasyonu ve üretim analitiği sunar.
 */

const QUICK_PROMPTS = [
  { id: 'repro', icon: Dna, title: 'Tohumlama & Östrus', query: 'Son 60 günde tohumlanmamış veya östrus göstermemiş sağmalları analiz et ve tohumlama protokolü öner.' },
  { id: 'milk', icon: Droplets, title: 'Süt Verim Düşüşü', query: 'Son 7 günde sağım litresi %15ten fazla azalan hayvanlar ve olası gizli mastitis/asidoz nedenleri nelerdir?' },
  { id: 'feed', icon: Utensils, title: 'Rasyon Tasarrufu', query: 'TMR yem rasyonunda süt verimini düşürmeden kaba-kesif yem maliyetini hayvan başı nasıl %10 optimize edebilirim?' },
  { id: 'mastitis', icon: ShieldAlert, title: 'Mastitis Erken Uyarı', query: 'CMT şüpheli çıkan çeyrekler için antibiyotiksiz erken sağaltım ve meme daldırma protokolü nedir?' },
  { id: 'cost', icon: DollarSign, title: 'Süt/Yem Paritesi', query: 'Mevcut çiğ süt litre fiyatı ve yem çuval maliyetine göre çiftliğin baş başı net marjı nedir?' }
];

export default function AiFarmAdvisorModal({ isOpen, onClose }) {
  const [messages, setMessages] = useState([
    {
      id: 1,
      sender: 'ai',
      text: `Merhaba! Ben **mFk Farm AI Çiftlik Danışmanınız**.

Sürünüzün süt verimi, tohumlama & üreme takvimi, TMR rasyon maliyet optimizasyonu veya veterinerlik konularında gerçek zamanlı analizler sunabilirim.

Hızlı bir analiz için yukarıdaki başlıklardan birine dokunabilir veya doğrudan aklınızdaki soruyu iletebilirsiniz.`,
      time: 'Şimdi'
    }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    if (isOpen) {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isOpen, loading]);

  if (!isOpen) return null;

  const handleSend = (textToSend) => {
    const query = textToSend || input;
    if (!query.trim()) return;

    const userMsg = {
      id: Date.now(),
      sender: 'user',
      text: query,
      time: new Date().toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' })
    };

    setMessages(prev => [...prev, userMsg]);
    if (!textToSend) setInput('');
    setLoading(true);

    setTimeout(() => {
      let replyText = '';
      const q = query.toLowerCase();

      if (q.includes('tohum') || q.includes('östrus') || q.includes('üreme')) {
        replyText = `🧬 **ÜREME & SÜRÜ ISLAH ANALİZİ:**\n\n• **Ultrason & Gebelik Muayenesi:** Sürünüzde tohumlama üzerinden 35+ gün geçmiş muayene bekleyen hayvanlar tespit edildi.\n• **V.P.G (Gönüllü Bekleme Süresi):** Doğumdan sonra 60 günü aşan inekler için östrus senkronizasyonu (Ovsynch veya PGF2α) planlanmalıdır.\n• **Tohumlama İndeksi:** Sürü hedefiniz 1.6 payet/gebelik olup, kızgınlık tespitinde aktivite tasmaları izlenmelidir.`;
      } else if (q.includes('süt') || q.includes('verim') || q.includes('litre')) {
        replyText = `🥛 **SÜT VERİMİ & LAKTASYON PERFORMANSI:**\n\n• **Mevcut Sürü Ortalaması:** ~28.4 L/gün. 305 günlük Wood laktasyon eğrisine göre 50–70. günler arası beklenen pik verim seviyesindedir.\n• **Verim Sapması:** Ani düşüş gösteren sağmallarda asidoz (SARA) veya gizli somatik hücre artışı (CMT) kontrolü yapılmalıdır.\n• **Soğuk Zincir:** Tank sıcaklığı +3.8°C seviyesinde mükemmel korunuyor.`;
      } else if (q.includes('rasyon') || q.includes('yem') || q.includes('maliyet') || q.includes('parite')) {
        replyText = `🌾 **TMR RASYON & MALİYET OPTİMİZASYONU:**\n\n• **Kuru Madde Hedefi:** Günlük 22.0 kg KM tüketimi sağlanmalıdır.\n• **Mısır Silajı / Fabrika Yemi Dengesi:** Silaj kuru maddesini %34 düzeyinde tutarak fabrika yemi tüketimini hayvan başı 1.2 kg azaltabilirsiniz.\n• **Tasarruf:** Bu optimizasyon günlük sürü bazında yaklaşık **₺850 tasarruf** sağlar (Süt/Yem paritesi: 1.45).`;
      } else if (q.includes('mastitis') || q.includes('cmt') || q.includes('meme')) {
        replyText = `🛡️ **MASTİTİS CMT & MEME SAĞLIĞI PROTOKOLÜ:**\n\n• **Şüpheli Çeyrekler (Skor 1):** Sağım öncesi daldırma solüsyonunun temas süresini 30 saniyeye çıkarın.\n• **Arınma Süresi:** İlaç tedavisi uygulanan ineklerin sütü tanka dökülmemeli, Hızlı Sağım Paneli'nde kırmızı arınma uyarısı takip edilmelidir.\n• **Erken Müdahale:** Nane yağı bazlı meme jelleri ve sık sağım ile klinik mastitise geçişi %70 engelleyebilirsiniz.`;
      } else {
        replyText = `🔍 **ÇİFTLİK YÖNETİM RAPORU:**\n\nSistem kayıtlarınıza göre çiftliğin IoT telemetrisi ve sürü verileri aktif olarak taranmaktadır:\n• İlaç arınma sürelerine titizlikle uyulduğu,\n• Tesis mikroklima (THI 68) değerinin konfor bandında olduğu,\n• Düve ve buzağı gelişim hızının standart eğriye uygun olduğu teyit edilmiştir.`;
      }

      setMessages(prev => [
        ...prev,
        {
          id: Date.now() + 1,
          sender: 'ai',
          text: replyText,
          time: new Date().toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' })
        }
      ]);
      setLoading(false);
    }, 650);
  };

  const handleCopyText = (txt) => {
    navigator.clipboard.writeText(txt);
    toast.success('Mesaj panoya kopyalandı!');
  };

  const handleResetChat = () => {
    setMessages([
      {
        id: 1,
        sender: 'ai',
        text: 'Sohbet sıfırlandı. Çiftliğinizle ilgili analiz etmek istediğiniz yeni bir konuyu yazabilirsiniz.',
        time: 'Şimdi'
      }
    ]);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 bg-slate-950/70 backdrop-blur-md animate-fade-in">
      <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden flex flex-col h-[650px] max-h-[92vh] border border-slate-100">
        {/* Üst Yönetici / AI Başlık */}
        <div 
          className="p-4 sm:p-5 text-white relative overflow-hidden"
          style={{ background: 'linear-gradient(135deg, #022c22 0%, #064e3b 45%, #0f172a 100%)' }}
        >
          <div className="absolute -right-8 -top-8 w-48 h-48 bg-emerald-400/10 rounded-full blur-2xl pointer-events-none" />
          
          <div className="flex items-center justify-between relative z-10">
            <div className="flex items-center gap-3">
              <div className="relative">
                <div className="w-11 h-11 rounded-2xl bg-gradient-to-br from-emerald-400 to-teal-600 flex items-center justify-center shadow-lg shadow-emerald-500/20 text-teal-950 font-black">
                  <Bot className="w-6 h-6 text-slate-950" />
                </div>
                <span className="absolute -bottom-1 -right-1 w-3.5 h-3.5 bg-emerald-400 border-2 border-slate-900 rounded-full animate-pulse" />
              </div>

              <div>
                <div className="flex items-center gap-2">
                  <h3 className="font-black text-base text-white tracking-tight">mFk Farm AI Çiftlik Danışmanı</h3>
                  <span className="px-2 py-0.5 rounded-full text-[10px] font-black bg-emerald-500/20 text-emerald-300 border border-emerald-400/30 flex items-center gap-1">
                    <Sparkles className="w-2.5 h-2.5" /> v2.5 Canlı
                  </span>
                </div>
                <p className="text-xs text-emerald-100/80 mt-0.5">Sürü verisi, laktasyon ve veterinerlik zekası</p>
              </div>
            </div>

            <div className="flex items-center gap-1.5">
              <button 
                onClick={handleResetChat} 
                title="Sohbeti Sıfırla"
                className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 text-white/80 hover:text-white flex items-center justify-center transition-all"
              >
                <RefreshCw className="w-3.5 h-3.5" />
              </button>
              <button 
                onClick={onClose} 
                className="w-8 h-8 rounded-full bg-white/10 hover:bg-white/20 text-white/80 hover:text-white flex items-center justify-center transition-all"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>

        {/* Hızlı Tavsiye Çipleri (Çirkin yatay scroll bar kaldırıldı) */}
        <div className="bg-emerald-950/5 border-b border-emerald-900/10 px-3 py-2.5 flex items-center gap-2 overflow-x-auto [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden shrink-0">
          <span className="text-[10px] font-bold text-gray-400 uppercase tracking-wider pl-1 shrink-0">
            Önerilen:
          </span>
          {QUICK_PROMPTS.map(p => {
            const Icon = p.icon;
            return (
              <button
                key={p.id}
                onClick={() => handleSend(p.query)}
                className="text-xs font-bold bg-white hover:bg-emerald-50 text-emerald-900 border border-emerald-200/80 px-3 py-1.5 rounded-full whitespace-nowrap transition-all flex items-center gap-1.5 shadow-2xs hover:scale-102 active:scale-98 shrink-0"
              >
                <Icon className="w-3.5 h-3.5 text-emerald-600" />
                <span>{p.title}</span>
                <ChevronRight className="w-3 h-3 text-emerald-400 opacity-60" />
              </button>
            );
          })}
        </div>

        {/* Mesaj Akışı */}
        <div className="flex-1 overflow-y-auto p-4 sm:p-5 space-y-4 bg-slate-50/70 scrollbar-thin">
          {messages.map((m) => {
            const isUser = m.sender === 'user';
            return (
              <div
                key={m.id}
                className={`flex items-start gap-3 ${isUser ? 'flex-row-reverse' : ''}`}
              >
                <div 
                  className={`w-8 h-8 rounded-2xl flex items-center justify-center shrink-0 text-xs font-black shadow-xs ${
                    isUser 
                      ? 'bg-gradient-to-br from-blue-600 to-indigo-700 text-white' 
                      : 'bg-gradient-to-br from-emerald-600 to-teal-800 text-white'
                  }`}
                >
                  {isUser ? 'Sen' : <Bot className="w-4 h-4" />}
                </div>

                <div 
                  className={`group relative max-w-[85%] p-4 rounded-3xl text-xs sm:text-sm leading-relaxed shadow-sm transition-all ${
                    isUser 
                      ? 'bg-gradient-to-br from-blue-600 to-blue-700 text-white rounded-tr-xs' 
                      : 'bg-white border border-gray-100 text-gray-800 rounded-tl-xs shadow-slate-200/60'
                  }`}
                >
                  <div className="whitespace-pre-line font-medium leading-relaxed">
                    {m.text}
                  </div>

                  <div className={`flex items-center justify-between gap-4 mt-2 pt-2 border-t ${isUser ? 'border-white/10 text-blue-200' : 'border-gray-100 text-gray-400'} text-[10px]`}>
                    <span>{m.time}</span>
                    {!isUser && (
                      <button
                        onClick={() => handleCopyText(m.text)}
                        className="opacity-0 group-hover:opacity-100 transition-opacity hover:text-emerald-700 flex items-center gap-1 font-semibold"
                        title="Cevabı Kopyala"
                      >
                        <Copy className="w-3 h-3" /> Kopyala
                      </button>
                    )}
                  </div>
                </div>
              </div>
            );
          })}

          {loading && (
            <div className="flex items-center gap-3 bg-white p-3.5 rounded-2xl border border-emerald-100 shadow-xs w-fit animate-pulse">
              <div className="w-6 h-6 rounded-xl bg-emerald-100 text-emerald-700 flex items-center justify-center">
                <Sparkles className="w-3.5 h-3.5 animate-spin" />
              </div>
              <div className="flex items-center gap-1.5 text-xs text-emerald-900 font-semibold">
                <span>mFk Danışman analiz hazırlıyor</span>
                <span className="flex gap-1">
                  <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce [animation-delay:-0.3s]" />
                  <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce [animation-delay:-0.15s]" />
                  <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-bounce" />
                </span>
              </div>
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>

        {/* Soru Giriş Alanı */}
        <div className="p-3 sm:p-4 bg-white border-t border-gray-100">
          <form 
            onSubmit={(e) => { e.preventDefault(); handleSend(); }}
            className="flex items-center gap-2 bg-slate-50 border border-slate-200/90 rounded-2xl px-3 py-1.5 focus-within:ring-2 focus-within:ring-emerald-500/20 focus-within:border-emerald-500 transition-all shadow-inner"
          >
            <Sparkles className="w-4 h-4 text-emerald-600 shrink-0 ml-1" />
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Sürünüz, süt verimi, rasyon veya aşılar hakkında bir soru yazın..."
              className="flex-1 text-xs sm:text-sm bg-transparent border-none py-2 px-2 focus:outline-none text-gray-900 placeholder-gray-400 font-medium"
            />
            <button
              type="submit"
              disabled={!input.trim() || loading}
              className="w-9 h-9 rounded-xl bg-emerald-600 hover:bg-emerald-500 disabled:opacity-30 disabled:hover:bg-emerald-600 text-white flex items-center justify-center transition-all shrink-0 shadow-sm active:scale-95"
            >
              <Send className="w-4 h-4" />
            </button>
          </form>

          <p className="text-[10px] text-gray-400 text-center mt-2">
            mFk Farm AI, sürü kayıtları ve modern veterinerlik kılavuzlarına dayanarak karar destek tavsiyesi üretir.
          </p>
        </div>
      </div>
    </div>
  );
}
